/* 04 / live editorial terrain print: real 7.5m contour SVG, three stroke groups.
 * Static one-time vector load; MERSI owns ALL progress; no independent clocks.
 * Original elevations are generated by scripts/build-olive-mountain-contours-v1.py.
 */
(()=>{'use strict';
 const stage=document.querySelector('#p2-olive-stage');
 const mount=document.querySelector('.olive-editorial-engraving__print--topography');
 if(!stage||!mount)return;
 let groups=null,progress=0;
 const clamp=v=>Math.max(0,Math.min(1,v));
 const ease=v=>{const t=clamp(v);return t*t*(3-2*t)};
 function paint(_plant,terrain){
  progress=clamp(terrain);
  if(!groups)return;
  const reveal=[
   ease(progress/.43),
   ease((progress-.19)/.55),
   ease((progress-.53)/.47)
  ];
  groups.forEach((g,i)=>{
   const offset=(1000*(1-reveal[i])).toFixed(3);
   if(g.getAttribute('stroke-dashoffset')!==offset)
    g.setAttribute('stroke-dashoffset',offset);
  });
 }
 window.P2OliveEngraving={paint};
 fetch('/images/p2-realms/v15/04-olive-mount-terrain-growth-v53.svg')
  .then(r=>{if(!r.ok)throw Error('terrain SVG HTTP '+r.status);return r.text()})
  .then(source=>{
   const doc=new DOMParser().parseFromString(source,'image/svg+xml');
   if(doc.querySelector('parsererror'))throw Error('invalid topographic SVG');
   const original=doc.documentElement;
   if(original.localName!=='svg')throw Error('not an SVG');
   const svg=document.importNode(original,true);
   svg.removeAttribute('width');svg.removeAttribute('height');
   svg.setAttribute('preserveAspectRatio','xMidYMid meet');
   svg.setAttribute('aria-hidden','true');
   groups=['major','mid','fine'].map(name=>{
    const el=svg.querySelector('.terrain-'+name);
    if(!el)throw Error('missing '+name+' contours');
    el.setAttribute('stroke-dashoffset','1000');
    return el;
   });
   mount.append(svg);
   mount.classList.add('has-path-growth');
   const p=Number(stage.dataset.p2EngravingTerrain||progress);
   paint(0,p);
   stage.dataset.p2TerrainStrokeEngine='real-dem-dash-v53';
  })
  .catch(err=>{
   stage.dataset.p2TerrainStrokeEngine='static-fallback';
   console.warn('P2 04 contour draw fallback',err.message);
  });
})();
